#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::string longestDiverseString(int a, int b, int c) {
        std::vector<std::pair<int, char>> counts = {{a, 'a'}, {b, 'b'}, {c, 'c'}};
        std::string res = "";
        while (true) {
            std::sort(counts.rbegin(), counts.rend());
            bool added = false;
            for (int i = 0; i < 3; ++i) {
                if (counts[i].first == 0) break;
                char ch = counts[i].second;
                int n = res.size();
                if (n >= 2 && res[n - 1] == ch && res[n - 2] == ch) continue;
                res += ch;
                counts[i].first--;
                added = true;
                break;
            }
            if (!added) break;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String longestDiverseString(int a, int b, int c) {
        int[][] counts = {{a, 0}, {b, 1}, {c, 2}};
        StringBuilder res = new StringBuilder();
        while (true) {
            Arrays.sort(counts, (x, y) -> Integer.compare(y[0], x[0]));
            boolean added = false;
            for (int i = 0; i < 3; i++) {
                if (counts[i][0] == 0) break;
                char ch = (char)('a' + counts[i][1]);
                int n = res.length();
                if (n >= 2 && res.charAt(n - 1) == ch && res.charAt(n - 2) == ch) continue;
                res.append(ch);
                counts[i][0]--;
                added = true;
                break;
            }
            if (!added) break;
        }
        return res.toString();
    }
}

var longestDiverseString = function(a, b, c) {
    const counts = [['a', a], ['b', b], ['c', c]];
    const res = [];
    while (true) {
        counts.sort((x, y) => y[1] - x[1]);
        let added = false;
        for (let i = 0; i < 3; i++) {
            const [ch, cnt] = counts[i];
            if (cnt === 0) break;
            const n = res.length;
            if (n >= 2 && res[n - 1] === ch && res[n - 2] === ch) continue;
            res.push(ch);
            counts[i][1]--;
            added = true;
            break;
        }
        if (!added) break;
    }
    return res.join('');
};
